import { expect, Page, Request } from '@playwright/test';
import { pp } from '../pricebook/pricebook-helpers';

export { ROLE, CLIENT, stamp, addManualItem, removeDocumentAt } from '../pricebook/pricebook-helpers';

export const CUSTOMER_REQUIRED = 'Select a customer to bill.';

/** EN-интерфейс до загрузки страницы. */
export async function setEnglish(page: Page) {
  await page.addInitScript(() => {
    try { window.localStorage.setItem('preferred-language', 'en'); } catch { /* ignore */ }
  });
}

/** New Invoice прямым адресом (тот же, что открывает Create new → New Invoice). */
export async function openNewInvoiceForm(page: Page) {
  await setEnglish(page);
  await page.goto(pp('/InvoiceForm?action=new'));
  await expect(page.getByText('Bill To:', { exact: true })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByRole('button', { name: 'Create Invoice' })).toBeVisible();
}

/** Запросы создания/изменения счёта (POST/PATCH/PUT на URL с invoice), без загрузки файлов страницы. */
export function watchInvoiceWrites(page: Page): string[] {
  const writes: string[] = [];
  page.on('request', (r: Request) => {
    if (['POST', 'PATCH', 'PUT'].includes(r.method()) && /invoice/i.test(r.url()) && ['fetch', 'xhr'].includes(r.resourceType())) {
      writes.push(`${r.method()} ${r.url()}`);
    }
  });
  return writes;
}

/** Красный текст под Bill To (role=alert). */
export const customerAlert = (page: Page) => page.getByRole('alert').filter({ hasText: CUSTOMER_REQUIRED });

/** Тост «Select a customer to bill.» (Radix toast — не role=alert у Bill To). */
export const customerToast = (page: Page) =>
  page.locator('li, [role="status"]').filter({ hasText: CUSTOMER_REQUIRED }).filter({ hasNot: page.getByRole('alert') }).first();

export const customerSearch = (page: Page) => page.getByPlaceholder('Search customer...');

/** Строка «Invoice name:» (span + блок с кнопками). */
export const invoiceNameRow = (page: Page) => page.getByText('Invoice name:', { exact: true }).locator('xpath=..');

/** Номер счёта из строки «Invoice number: …». */
export async function invoiceNumber(page: Page): Promise<string> {
  const row = page.getByText('Invoice number:', { exact: true }).locator('xpath=..');
  return ((await row.innerText()).replace('Invoice number:', '')).trim();
}

/** Bill To → выбрать клиента из открытого списка (или открыть его через «Select a customer» / Change). */
export async function pickCustomer(page: Page, name: string) {
  const search = customerSearch(page);
  if (!(await search.isVisible())) {
    await page.getByText('Select a customer', { exact: true }).or(page.getByRole('button', { name: 'Change' })).first().click();
  }
  await search.fill(name);
  await page.getByText(name, { exact: true }).filter({ visible: true }).first().click();
}

