// и проверяется перед любым действием (context.md 14.10). Адреса относительные (baseURL конфига = app.techory.ai).
// Разметка сверена с бандлом app.techory.ai 12.11 (Invoices: номер счёта — кнопка «INV-…» → /InvoiceForm?id=…&action=edit;
// InvoiceForm: «Select a customer», «Same as billing address», «No items added yet», «Invoice number:» N/A у нового;
// номер нового счёта назначается при Create Invoice, позиции до этого — локальные) и скриншотами a901b1-v2-*.
export const PROD_ROLE = 'admin';
export const TEST_COMPANY_ID = '4432bd2f-3f47-43cf-8ef2-b0c16436f025'; // «test»
export const PROD_CLIENT = 'QA-unit client';

/** EN-интерфейс и компания «test» до загрузки страницы (на каждой вкладке). */
export async function prepareProdTest(page: Page) {
  await page.addInitScript((company) => {
    try {
      window.localStorage.setItem('preferred-language', 'en');
      window.localStorage.setItem('selected-company-id', company);
    } catch { /* ignore */ }
  }, TEST_COMPANY_ID);
}

/** Выбрана именно компания «test» (не реальная компания клиента). */
export async function expectTestCompany(page: Page) {
  await expect
    .poll(() => page.evaluate(() => window.localStorage.getItem('selected-company-id')), { message: 'выбрана компания «test»' })
    .toBe(TEST_COMPANY_ID);
}

/** Invoices → открыть первый существующий счёт (кнопка с номером INV-…). Возвращает его номер. */
export async function openExistingInvoice(page: Page): Promise<string> {
  await page.goto('/invoices');
  await expectTestCompany(page);
  const numberBtn = page.getByRole('button', { name: /^INV-\d+$/ }).first();
  await expect(numberBtn, 'в компании test есть хотя бы один счёт (предусловие)').toBeVisible({ timeout: 30_000 });
  const number = (await numberBtn.innerText()).trim();
  await numberBtn.click();
  await page.waitForURL(/\/InvoiceForm\?id=/i);
  await expect.poll(() => invoiceNumber(page), { message: 'номер открытого счёта' }).toBe(number);
  return number;
}

/** New Invoice прямым адресом на prod (компания «test»). */
export async function openNewInvoiceProd(page: Page) {
  await page.goto('/InvoiceForm?action=new');
  await expectTestCompany(page);
  await expect(page.getByText('Bill To:', { exact: true })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByRole('button', { name: 'Create Invoice' })).toBeVisible();
  await expect.poll(() => invoiceNumber(page)).toBe('N/A');
}

/** После Create Invoice: кнопки Create Invoice нет, адрес /InvoiceForm?id=…, номер INV-… Возвращает { number, url }. */
export async function waitInvoiceCreated(page: Page): Promise<{ number: string; url: string }> {
  await expect(page.getByRole('button', { name: 'Create Invoice' })).toHaveCount(0, { timeout: 30_000 });
  await page.waitForURL(/\/InvoiceForm\?id=/i, { timeout: 30_000 });
  await expect.poll(() => invoiceNumber(page), { message: 'номер созданного счёта' }).toMatch(/^INV-\d+$/);
  return { number: await invoiceNumber(page), url: page.url() };
}
